//=============================================================================
// usb_pid_checker.sv
// SUB-BLOCK 1 : Packet Identifier (PID) Checker  (combinational decode)
//
// Function (USB2.0 Spec 8.3.1 / Figure 8-1):
//   "A PID consists of a four-bit packet type field followed by a four-bit
//    check field ... The PID check field is generated by performing a one's
//    complement of the packet type field. A PID error exists if the four
//    PID check bits are not complements of their respective packet
//    identifier bits."
//
// Purely combinational: given one raw byte from the Link Layer (already
// NRZI-decoded / bit-unstuffed / de-serialized) it:
//   - checks the complement relationship  byte[7:4] == ~byte[3:0]
//   - extracts the PID group  (byte[1:0])
//   - extracts the PID type field (byte[3:0])
// The enclosing (sequential) top module is responsible for capturing this
// decode at the correct byte-time (the PID byte only occupies byte #1 of a
// handshake packet).
//=============================================================================
import usb_pid_pkg::*;

module usb_pid_checker (
    input  logic [7:0]  pid_byte_i,     // raw byte from link layer

    output logic        pid_chk_ok_o,   // 1 = complement check passed
    output pid_group_e  pid_group_o,    // PID group  (type field bits <1:0>)
    output pid_type_e   pid_type_o      // PID type field (byte[3:0])
);

    logic [3:0] type_field;
    logic [3:0] check_field;

    assign type_field  = pid_byte_i[3:0];
    assign check_field = pid_byte_i[7:4];

    always_comb begin
        pid_chk_ok_o = (check_field == ~type_field);
        pid_group_o  = pid_group_e'(type_field[1:0]);
        pid_type_o   = pid_type_e'(type_field);
    end

endmodule : usb_pid_checker
